package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;

/** The rules a claim must keep to be added to a person (see AddClaim), checked without writing anything. */
public final class ClaimRules {

    private ClaimRules() {
    }

    /** The claim's date (the sheet's entry date, else its today, when none was given) and the due-by it would be fixed with (see dueBy);
     *  a due-by inside a closed period or a date after the person's retirement date is refused, as is a negative amount that does not
     *  correct a SETTLED claim (see Corrections). */
    public static Checked check(Person person, ClaimValues values, SettingRepository settings, PeriodRepository periods,
            ClaimRepository claims, HolidayRepository holidays) throws InvalidClaimException {
        LocalDate date = values.date() != null ? values.date() : settings.claimDate(person.sheetId());
        LocalDate dueBy = dueBy(person, date, settings, holidays);
        if (periods.closedOn(person.sheetId(), dueBy)) {
            throw new InvalidClaimException("The claim's due-by is inside a closed period");
        }
        if (!person.mayClaimOn(date)) {
            throw new InvalidClaimException("The claim's date is after the person's retirement date");
        }
        return new Checked(date, Corrections.check(person.sheetId(), person.id(), values, claims), dueBy);
    }

    /** The due-by a claim of the person dated the date is fixed with as it is added: its date plus the person's own terms, else the
     *  terms of their grade in force on that date; when that falls on a holiday of the sheet, the next day that is not one (the holidays on the
     *  sheet now decide: one added later leaves the due-by as it is). */
    public static LocalDate dueBy(Person person, LocalDate date, SettingRepository settings, HolidayRepository holidays) {
        return holidays.notOnHoliday(person.sheetId(),
                date.plusDays(settings.terms(person.sheetId(), person.terms(), person.gradeOn(date), date)));
    }

    /** A claim's date, the number it corrects (null when none) and its due-by, once its rules are kept. */
    public record Checked(LocalDate date, String corrects, LocalDate dueBy) {
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Stores the claim's remaining amount, but only while it is still OPEN with the amount the split started from (a
 * change another user made first is refused), then adds the new claim: the split-off amount, the same person, date
 * and note, its due-by fixed now from the person's own terms, else those of their grade in force on its date, OPEN with the sheet's next
 * number (see ClaimNumbering), opened by the user who split, and the original's number as split-from; a late entry when its
 * due-by falls inside a soft-closed period. The new claim's
 * status log starts with its OPEN line (see ClaimLog).
 */
public class SaveSplit {
    public void save(@Val Claim claim, @Val ClaimSplit split, ClaimRepository claims, PersonRepository people,
            PeriodRepository periods, SettingRepository settings, SheetRepository sheets, ClaimLog log,
            Out<SplitOff> made) throws InvalidClaimStatusException {
        if (!claims.split(claim, claim.amount().add(split.amount()))) {
            throw new InvalidClaimStatusException("The claim was changed by someone else");
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        String grade = person == null ? null : person.gradeOn(claim.date());
        Claim added = claims.add(claim.sheetId(), claim.personId(), split.amount(), claim.date(), claim.note(), null,
                claim.date().plusDays(settings.terms(claim.sheetId(), person == null ? null : person.terms(), grade, claim.date())));
        if (periods.softClosedOn(added.sheetId(), added.dueBy())) {
            claims.markLateEntry(added);
        }
        String number = ClaimNumbering.next(added, claims, periods, settings, sheets);
        Claim opened = new Claim(added.id(), added.sheetId(), added.personId(), added.amount(), added.date(),
                added.note(), ClaimStatus.OPEN, number, null, split.by(), false, null, null, added.dueBy(), null, 0,
                claim.number());
        claims.updateStatus(opened, ClaimStatus.DRAFT);
        claims.splitFrom(opened);
        log.write(opened, split.by());
        made.set(new SplitOff(opened));
    }
}
package net.officefloor.hq.app.holiday;

import java.sql.Date;
import java.time.LocalDate;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The stored holidays, kept per sheet. */
@Repository
public class HolidayRepository {

    private final JdbcTemplate jdbc;

    public HolidayRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's holidays, by date. */
    public List<LocalDate> list(String sheetId) {
        return jdbc.query("SELECT holiday_date FROM holiday WHERE sheet_id = ? ORDER BY holiday_date",
                (rs, n) -> rs.getObject("holiday_date", LocalDate.class), sheetId);
    }

    /** Adds the holiday; false when the date is already one (the primary key refuses a second). */
    public boolean add(String sheetId, LocalDate date) {
        try {
            jdbc.update("INSERT INTO holiday (sheet_id, holiday_date) VALUES (?, ?)", sheetId, Date.valueOf(date));
            return true;
        } catch (DuplicateKeyException e) {
            return false;
        }
    }

    /** The date itself when it is not a holiday of the sheet, else the next day that is not. */
    public LocalDate notOnHoliday(String sheetId, LocalDate date) {
        Set<LocalDate> holidays = new HashSet<>(list(sheetId));
        LocalDate day = date;
        while (holidays.contains(day)) {
            day = day.plusDays(1);
        }
        return day;
    }
}
import { isOpen, type Claim } from '../claims/claims';

/** What the late charge on a sheet depends on: its today (yyyy-MM-dd, '' while it loads), its
 *  late percent in force on a date (two decimals; a claim's charge takes the one in force on each of its 30-day boundaries) and its policy date (yyyy-MM-dd; its today while blank): a claim whose `roundsOn` is
 *  before it rounds its live figures half up, one on or after it half to even. */
export type Late = { today: string; pct: (date: string) => string; policy: string };

/** Whether the claim's live figures round half up (it rounds on a date before the policy date) rather than half to even. */
export function roundsHalfUp(claim: Claim, late: Late | undefined): boolean {
  return late !== undefined && late.policy !== '' && claim.roundsOn < late.policy;
}

/** Days since 1970-01-01 of a yyyy-MM-dd date. */
export function day(date: string): number {
  const [y, m, d] = date.split('-').map(Number);
  return Date.UTC(y, m - 1, d) / 86_400_000;
}

/** A claim's due-by (yyyy-MM-dd): fixed when it was added, its date plus its person's own terms then, else those of their grade. */
export function dueBy(claim: Claim): string {
  return claim.dueBy;
}

/** Whether a claim is overdue: it is open (OPEN or PENDING), not deferred, and its due-by is before the sheet's today. */
export function isOverdue(claim: Claim, today: string): boolean {
  return isOpen(claim) && !claim.deferred && today !== '' && dueBy(claim) < today;
}

/** How many full 30 days an overdue claim is overdue (0 when it is not overdue, its due is fixed by settling, or it is a
 *  correction, which bears no late charge). */
export function lateSteps(claim: Claim, late: Late): number {
  if (claim.due !== null || claim.amount.trim().startsWith('-') || !isOverdue(claim, late.today)) return 0;
  return Math.floor((day(late.today) - day(dueBy(claim))) / 30);
}

/** A yyyy-MM-dd date the given days after another. */
export function plusDays(date: string, days: number): string {
  return new Date((day(date) + days) * 86_400_000).toISOString().slice(0, 10);
}

/** The 30-day boundaries an overdue claim has passed (its due-by plus 30, 60, 90 ... days, on or before today), each
 *  bearing the late percent in force on it; none when it bears no late charge (see lateSteps). */
export function lateBoundaries(claim: Claim, late: Late): string[] {
  const steps = lateSteps(claim, late);
  return Array.from({ length: steps }, (_, i) => plusDays(dueBy(claim), 30 * (i + 1)));
}
